def _mk(q, ans, spread, fmt=str):
    s = {ans}
    while len(s) < 4:
        v = ans + random.choice([-1, 1]) * random.randint(1, spread)
        if v > 0: s.add(v)
    l = list(s); random.shuffle(l)
    return {"q": q, "o": [fmt(x) for x in l], "a": l.index(ans), "skill": "aptitude"}

def gen_aptitude(k):
    """Freshly generated numeric aptitude questions: every candidate gets different numbers."""
    out, seen = [], set()
    while len(out) < k:
        t = random.randrange(6)
        if t == 0: a, b = random.randint(13, 49), random.randint(3, 9); x = _mk(f"What is {a} × {b}?", a * b, 12)
        elif t == 1: p = random.choice(range(10, 95, 5)); n = random.choice(range(40, 501, 20)); x = _mk(f"What is {p}% of {n}?", p * n // 100, 15)
        elif t == 2: a, d = random.randint(2, 15), random.randint(2, 9); x = _mk(f"Find the next number: {a}, {a+d}, {a+2*d}, {a+3*d}, ?", a + 4 * d, 6)
        elif t == 3: s, h = random.randint(30, 90), random.randint(2, 6); x = _mk(f"A vehicle covers {s*h} km in {h} hours. Average speed in km/h?", s, 10)
        elif t == 4: P, r, y = random.choice(range(1000, 10001, 1000)), random.randint(4, 12), random.randint(2, 5); x = _mk(f"Simple interest on ₹{P} at {r}% per year for {y} years?", P * r * y // 100, 50, lambda v: f"₹{v}")
        else: n = random.randint(9, 63); x = _mk(f"What is the decimal value of binary {bin(n)[2:]}?", n, 5)
        if x["q"] not in seen: seen.add(x["q"]); out.append(x)
    return out
